package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
final class AutomationUi {
 static String seconds(long ms){return String.format(Locale.US,"%.1f s",ms/1000.0);}
 static void general(Activity a,ActionType action,Runnable changed,Runnable start){LinearLayout body=Ui.column(a);body.setPadding(Ui.dp(a,18),Ui.dp(a,12),Ui.dp(a,18),Ui.dp(a,12));ScrollView scroll=new ScrollView(a);scroll.addView(body);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(action.label+" · General").setView(scroll).setNegativeButton("Done",null).create();Runnable[] redraw=new Runnable[1];redraw[0]=()->{body.removeAllViews();body.addView(Ui.label(a,"Repeat at fixed screen positions without image recognition. All enabled General actions run together. Edits apply when you start or restart the session.",13,Ui.MUTED));try{List<TimedAction> list=AutomationStore.load(a,false);for(TimedAction item:list)if(item.action==action)row(a,body,item,false,()->{redraw[0].run();changed.run();});Button add=Ui.button(a,"+ Add timed "+action.label.toLowerCase(Locale.ROOT),true);LinearLayout.LayoutParams addLp=new LinearLayout.LayoutParams(-1,-2);addLp.topMargin=Ui.dp(a,16);addLp.bottomMargin=Ui.dp(a,12);body.addView(add,addLp);add.setOnClickListener(v->edit(a,false,TimedAction.create(action),true,()->{redraw[0].run();changed.run();}));Button run=Ui.button(a,"Start General mode",false);body.addView(run);run.setOnClickListener(v->{dialog.dismiss();a.getSharedPreferences("config",0).edit().putString("runMode","general").commit();start.run();});}catch(RuntimeException e){body.addView(Ui.label(a,e.getMessage(),14,Ui.RED));}};redraw[0].run();dialog.show();}
 static void timeline(Activity a,LinearLayout body,Runnable changed,Runnable start){TextView eyebrow=Ui.label(a,"SEQUENCE BUILDER",11,Ui.accent(4));eyebrow.setLetterSpacing(.14f);eyebrow.setPadding(0,0,0,Ui.dp(a,12));body.addView(eyebrow);TextView heading=Ui.label(a,"Timeline",32,Ui.CREAM);heading.setPadding(0,0,0,Ui.dp(a,12));body.addView(heading);body.addView(Ui.label(a,"Run a sequence without image detection. Each wait begins after the previous step completes. Edits apply on restart.",13,Ui.MUTED));Switch loop=new ActiveSwitch(a);loop.setText("Repeat timeline");loop.setChecked(AutomationStore.loop(a));Ui.polish(loop);body.addView(loop);loop.setOnCheckedChangeListener((v,on)->a.getSharedPreferences("automation",0).edit().putBoolean("loop",on).commit());try{List<TimedAction> list=AutomationStore.load(a,true);if(list.isEmpty())body.addView(Ui.label(a,"Add your first step, then choose its delay and screen position.",14,Ui.MUTED));for(int i=0;i<list.size();i++){body.addView(Ui.label(a,(i+1)+"  ↓  Wait "+seconds(list.get(i).delay),12,Ui.GREEN));row(a,body,list.get(i),true,changed);}Button add=Ui.button(a,"+ Add step",true);LinearLayout.LayoutParams addLp=new LinearLayout.LayoutParams(-1,-2);addLp.topMargin=Ui.dp(a,16);addLp.bottomMargin=Ui.dp(a,12);body.addView(add,addLp);add.setOnClickListener(v->edit(a,true,TimedAction.create(ActionType.TAP),true,changed));Button run=Ui.button(a,"Start Timeline mode",false);body.addView(run);run.setOnClickListener(v->{a.getSharedPreferences("config",0).edit().putString("runMode","timeline").commit();start.run();});}catch(RuntimeException e){body.addView(Ui.label(a,e.getMessage(),14,Ui.RED));}}
 static void row(Activity a,LinearLayout parent,TimedAction item,boolean timeline,Runnable changed){LinearLayout card=Ui.column(a);card.setPadding(Ui.dp(a,14),Ui.dp(a,12),Ui.dp(a,14),Ui.dp(a,12));card.setBackground(Ui.shape(a,Ui.SURFACE,Ui.LINE,18));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=Ui.dp(a,8);cp.bottomMargin=Ui.dp(a,16);parent.addView(card,cp);Switch enabled=new ActiveSwitch(a);enabled.setText(item.title());enabled.setChecked(item.enabled);Ui.polish(enabled);card.addView(enabled);card.addView(Ui.label(a,item.action.label+" · "+(timeline?"wait ":"every ")+seconds(item.delay)+(item.action.navigation()?"":String.format(Locale.US," · %.0f%%, %.0f%%",item.x*100,item.y*100)),12,Ui.MUTED));enabled.setOnCheckedChangeListener((v,on)->mutate(a,timeline,item.id,list->{for(int i=0;i<list.size();i++)if(list.get(i).id.equals(item.id))list.set(i,item.enabled(on));},changed));LinearLayout tools=new LinearLayout(a);card.addView(tools);addButton(a,tools,"Edit",()->edit(a,timeline,item,false,changed));if(timeline){addButton(a,tools,"↑",()->move(a,item.id,-1,changed));addButton(a,tools,"↓",()->move(a,item.id,1,changed));}addButton(a,tools,"Delete",()->new AlertDialog.Builder(a).setTitle("Delete this action?").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->mutate(a,timeline,item.id,list->list.removeIf(x->x.id.equals(item.id)),changed)).show());}
 static void addButton(Activity a,LinearLayout row,String label,Runnable click){Button b=Ui.button(a,label,false);b.setTextSize(12);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,Ui.dp(a,48),1);if(row.getChildCount()>0)bp.leftMargin=Ui.dp(a,8);row.addView(b,bp);b.setPadding(0,Ui.dp(a,8),0,Ui.dp(a,8));if(label.equals("↑"))b.setContentDescription("Move step up");if(label.equals("↓"))b.setContentDescription("Move step down");if(label.equals("Delete"))b.setTextColor(Ui.RED);b.setOnClickListener(v->click.run());}
 interface Change{void run(List<TimedAction> list);}
 static void mutate(Activity a,boolean timeline,String id,Change change,Runnable changed){try{List<TimedAction> list=AutomationStore.load(a,timeline);change.run(list);AutomationStore.save(a,timeline,list);changed.run();}catch(Exception e){Toast.makeText(a,e.getMessage(),Toast.LENGTH_LONG).show();}}
 static void move(Activity a,String id,int delta,Runnable changed){mutate(a,true,id,list->{for(int i=0;i<list.size();i++)if(list.get(i).id.equals(id)){int to=i+delta;if(to>=0&&to<list.size())Collections.swap(list,i,to);break;}},changed);}
 static EditText field(Activity a,LinearLayout form,String label,String value,boolean numeric){form.addView(Ui.label(a,label,13,Ui.CREAM));EditText e=new EditText(a);e.setSingleLine();e.setText(value);if(numeric)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);Ui.polish(e);form.addView(e,new LinearLayout.LayoutParams(-1,Ui.dp(a,48)));return e;}
 static long millis(String text){double n=Double.parseDouble(text.trim().replace(',','.'));if(!Double.isFinite(n)||n<.1||n>3600)throw new IllegalArgumentException("Delay must be 0.1–3600 seconds.");return Math.round(n*1000);}
 static void edit(Activity a,boolean timeline,TimedAction original,boolean adding,Runnable changed){LinearLayout form=Ui.column(a);form.setPadding(Ui.dp(a,20),Ui.dp(a,12),Ui.dp(a,20),Ui.dp(a,12));EditText name=field(a,form,"Name (optional)",original.name,false);final ActionType[] action={original.action};final float[] point={original.x,original.y,original.endX,original.endY};Spinner type=new Spinner(a);String[] names=Arrays.stream(ActionType.values()).map(x->x.label).toArray(String[]::new);type.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));type.setSelection(original.action.ordinal());if(timeline){form.addView(Ui.label(a,"Action",13,Ui.CREAM));form.addView(type);}EditText delay=field(a,form,timeline?"Wait after previous action (seconds)":"Interval after completion (seconds)",String.format(Locale.US,"%.1f",original.delay/1000.0),true);EditText duration=field(a,form,"Touch / swipe duration (milliseconds)",Integer.toString(original.duration),true);TextView coordinates=Ui.label(a,"",12,Ui.MUTED);form.addView(coordinates);Button position=Ui.button(a,"Place marker on screen",false);form.addView(position);Runnable update=()->{coordinates.setText(action[0].navigation()?"Android navigation · no marker required":String.format(Locale.US,"Start %.1f%%, %.1f%%%s",point[0]*100,point[1]*100,action[0].swipe()?String.format(Locale.US," → %.1f%%, %.1f%%",point[2]*100,point[3]*100):""));position.setVisibility(action[0].navigation()?View.GONE:View.VISIBLE);duration.setEnabled(!action[0].navigation());};update.run();type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){ActionType chosen=ActionType.values()[n];if(chosen!=action[0]){action[0]=chosen;TimedAction defaults=TimedAction.create(chosen);point[0]=defaults.x;point[1]=defaults.y;point[2]=defaults.endX;point[3]=defaults.endY;duration.setText(Integer.toString(defaults.duration));update.run();}}});
  position.setOnClickListener(v->{if(TapService.instance==null){Toast.makeText(a,"Enable AutoBash Accessibility to place markers over another app.",Toast.LENGTH_LONG).show();a.startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS));return;}TimedAction draft=new TimedAction(original.id,name.getText().toString(),action[0],point[0],point[1],point[2],point[3],original.delay,original.duration,true);TapService.instance.pickMarker(a,draft,result->{if(result!=null){System.arraycopy(result,0,point,0,4);update.run();}});});ScrollView scroll=new ScrollView(a);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(a).setTitle(adding?"Add timed action":"Edit timed action").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.show();dialog.getButton(-1).setOnClickListener(v->{try{long ms=millis(delay.getText().toString());int dur=action[0].navigation()?100:Integer.parseInt(duration.getText().toString());TimedAction edited=new TimedAction(original.id,name.getText().toString(),action[0],point[0],point[1],point[2],point[3],ms,dur,original.enabled);List<TimedAction> list=AutomationStore.load(a,timeline);boolean found=false;for(int i=0;i<list.size();i++)if(list.get(i).id.equals(original.id)){list.set(i,edited);found=true;break;}if(!found){if(!adding)throw new IllegalStateException("This action was removed; reopen the editor.");list.add(edited);}AutomationStore.save(a,timeline,list);dialog.dismiss();changed.run();}catch(Exception e){Toast.makeText(a,e.getMessage()==null?"Check the values":e.getMessage(),Toast.LENGTH_LONG).show();}});
 }
}
